import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.Statement;

public class VulnerableLogin {
    public boolean checkUser(String username, String password) throws Exception {
        // This code is vulnerable because it concatenates user input directly into the SQL query
        Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/test", "user", "pass");
        Statement stmt = conn.createStatement();

        // Improper use of Statement with string concatenation allows SQL injection
        String query = "SELECT * FROM users WHERE username='" + username + "' AND password='" + password + "'";
