        return rs.next();
    }
}
***
// GOOD CODE: Uses PreparedStatement to prevent SQL injection by properly parameterizing queries
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;

public class SecureLogin {
    public boolean checkUser(String username, String password) throws Exception {
        // Use PreparedStatement to safely handle user input and prevent SQL injection
        Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/test", "user", "pass");

        // Parameterized query ensures user input is treated as data, not executable code
        String query = "SELECT * FROM users WHERE username=? AND password=?";
        PreparedStatement pstmt = conn.prepareStatement(query);

        // Set parameters safely using setString method
        pstmt.setString(1, username);
        pstmt.setString(2, password);

        ResultSet rs = pstmt.executeQuery();
        return rs.next();
    }
}
